"""
LR scheduler wrappers matching the WarmupMultiStepLR interface
(get_lr() + step()) used by processor_clipreid_stage2.

Both wrappers share the same two-phase structure:
  1. Linear warmup: LR ramps from base_lr * warmup_factor → base_lr over warmup_epochs
  2. Scheduler phase (begins after warmup):
       AdaptiveLRWrapper  → ReduceLROnPlateau (drops only when loss plateaus)
       CosineRestartWrapper → CosineAnnealingWarmRestarts (periodic smooth resets)
"""
from torch.optim.lr_scheduler import ReduceLROnPlateau, CosineAnnealingWarmRestarts


class _WarmupBase:
    """Shared warmup logic."""
    def __init__(self, optimizer, warmup_epochs, warmup_factor):
        self._optimizer = optimizer
        self._base_lrs = [pg['lr'] for pg in optimizer.param_groups]
        self._warmup_epochs = warmup_epochs
        self._warmup_factor = warmup_factor
        self._epoch = 0
        self._set_warmup_lr(0)

    def _set_warmup_lr(self, epoch):
        alpha = self._warmup_factor + (1.0 - self._warmup_factor) * epoch / max(self._warmup_epochs, 1)
        for pg, base_lr in zip(self._optimizer.param_groups, self._base_lrs):
            pg['lr'] = base_lr * alpha

    def get_lr(self):
        return [pg['lr'] for pg in self._optimizer.param_groups]

    def set_metric(self, val):
        pass


class AdaptiveLRWrapper(_WarmupBase):
    def __init__(self, optimizer, warmup_epochs=10, warmup_factor=0.1,
                 patience=5, factor=0.5, min_lr=1e-7):
        super().__init__(optimizer, warmup_epochs, warmup_factor)
        self._scheduler = ReduceLROnPlateau(
            optimizer, mode='min', patience=patience, factor=factor, min_lr=min_lr,
        )
        self._metric = None

    def set_metric(self, val):
        self._metric = val

    def step(self):
        self._epoch += 1
        if self._epoch <= self._warmup_epochs:
            self._set_warmup_lr(self._epoch)
        elif self._metric is not None:
            self._scheduler.step(self._metric)


class CosineRestartWrapper(_WarmupBase):
    """Warmup then CosineAnnealingWarmRestarts.

    T_0: epochs per restart cycle (counted from end of warmup)
    T_mult: cycle length multiplier (1=constant, 2=doubling)
    """
    def __init__(self, optimizer, warmup_epochs=10, warmup_factor=0.1,
                 T_0=10, T_mult=1, eta_min=1e-7):
        super().__init__(optimizer, warmup_epochs, warmup_factor)
        # Restore true base LRs before cosine init so it captures correct base_lrs,
        # then drop back to warmup start. Without this, cosine cycles around the
        # warmup-reduced LR (10x too low).
        for pg, base_lr in zip(optimizer.param_groups, self._base_lrs):
            pg['lr'] = base_lr
        self._cosine = CosineAnnealingWarmRestarts(
            optimizer, T_0=T_0, T_mult=T_mult, eta_min=eta_min,
        )
        self._set_warmup_lr(0)

    def step(self):
        self._epoch += 1
        if self._epoch <= self._warmup_epochs:
            self._set_warmup_lr(self._epoch)
        else:
            self._cosine.step()

        dev = qml.device(device_name, wires=n_q)

        if entanglement == "full":
            # Standard StronglyEntanglingLayers
            weight_shape = qml.StronglyEntanglingLayers.shape(n_layers=n_layers, n_wires=n_q)
            self.qlayer_weights = nn.Parameter(torch.zeros(weight_shape))

            @qml.qnode(dev, interface="torch", diff_method="backprop")
            def _circuit(angles_2d, weights):
                for t in range(seq_len):
                    qml.AngleEmbedding(angles_2d[t], wires=range(n_q), rotation="Y")
                    qml.StronglyEntanglingLayers(weights, wires=range(n_q))
                return qml.probs(wires=range(n_q))

        else:
            # Ring or linear: rotation params [n_layers, n_q, 2] (RY + RZ per qubit)
            self.qlayer_weights = nn.Parameter(torch.zeros(n_layers, n_q, 2))

            if entanglement == "ring":
                @qml.qnode(dev, interface="torch", diff_method="backprop")
                def _circuit(angles_2d, weights):
                    # angles_2d: [T, B, n_q]; weights: [n_layers, n_q, 2]
                    for t in range(seq_len):
                        qml.AngleEmbedding(angles_2d[t], wires=range(n_q), rotation="Y")
                        for layer in range(n_layers):
                            # Nearest-neighbour ring entanglement
                            for i in range(n_q):
                                qml.CNOT(wires=[i, (i + 1) % n_q])
                            # Per-qubit rotations
                            for i in range(n_q):
                                qml.RY(weights[layer, i, 0], wires=i)
                                qml.RZ(weights[layer, i, 1], wires=i)
                    return qml.probs(wires=range(n_q))

            else:  # linear
                @qml.qnode(dev, interface="torch", diff_method="backprop")
                def _circuit(angles_2d, weights):
                    for t in range(seq_len):
                        qml.AngleEmbedding(angles_2d[t], wires=range(n_q), rotation="Y")
                        for layer in range(n_layers):
                            # Linear chain entanglement (most hardware-friendly)
                            for i in range(n_q - 1):
                                qml.CNOT(wires=[i, i + 1])
                            for i in range(n_q):
                                qml.RY(weights[layer, i, 0], wires=i)
                                qml.RZ(weights[layer, i, 1], wires=i)
                    return qml.probs(wires=range(n_q))

        self.circuit = _circuit

    self.upscale = nn.Linear(self.n_measurements, in_features, bias=False)
    self._init_weights()

def _init_weights(self):
    nn.init.kaiming_normal_(self.pre_net.weight, a=0, mode="fan_in")
    if not self.bypass_quantum:
        nn.init.normal_(self.qlayer_weights, mean=0, std=0.01)
    nn.init.normal_(self.upscale.weight, mean=0, std=0.001)

def _apply(self, fn):
    super()._apply(fn)
    if not self.bypass_quantum:
        self.qlayer_weights.data = self.qlayer_weights.data.cpu().float()
    return self

def forward(self, x: torch.Tensor) -> torch.Tensor:
    mean_feat = x.mean(1)
    if self.bypass_quantum:
        return mean_feat

    input_dtype  = x.dtype
    input_device = x.device
    B, T, D = x.shape

    angles = torch.sigmoid(self.pre_net(x.float().reshape(B * T, D))) * math.pi
    angles = angles.reshape(B, T, self.n_qubits)

    angles_cpu  = angles.permute(1, 0, 2).cpu().float()
    weights_cpu = self.qlayer_weights.cpu().float()

    q_out = self.circuit(angles_cpu, weights_cpu).float().to(input_device)
    delta = self.upscale(q_out)

    return (mean_feat.float() + delta).to(input_dtype)

def extra_repr(self) -> str:
    return (
        f"in_features={self.in_features}, n_qubits={self.n_qubits}, "
        f"n_layers={self.n_layers}, entanglement={self.entanglement}, "
        f"bypass={self.bypass_quantum}"
    )

    # Transpose to [T, B, n_q] so circuit[t] = [B, n_q] → PennyLane broadcasts over B.
    angles_cpu  = angles.permute(1, 0, 2).cpu().float()  # [T, B, n_q]
    weights_cpu = self.qlayer_weights.cpu().float()

    q_out = self.circuit(angles_cpu, weights_cpu).float().to(input_device)  # [B, 2^n_q]

    delta = self.upscale(q_out)   # [B, in_features]

    return (mean_feat.float() + delta).to(input_dtype)

def extra_repr(self) -> str:
    return (
        f"in_features={self.in_features}, n_qubits={self.n_qubits}, "
        f"n_layers={self.n_layers}, seq_len={self.seq_len}, "
        f"n_measurements={self.n_measurements}, bypass={self.bypass_quantum}"
    )

